mapper.select:
select * from (SELECT capc.property_contract_id, capc.over_due, capc.contract_id, capc.project_id, capc.product_id, capc.total_principal, capc.total_interest, capc.uncollected_principal, capc.uncollected_interest, capc.document_type, fc.contract_number, fc.contract_name, ( SELECT hbm.bp_name FROM hls_bp_master hbm, fct_project_bp fpb WHERE hbm.bp_id = fpb.bp_id AND fpb.project_id = fc.project_id AND fpb.credit_grantor_party = 'Y' ) AS bp_name FROM ct_abs_property_contract capc, fct_contract fc where capc.contract_id = fc.contract_id and capc.document_type = 'FCT_CONTRACT'
UNION
SELECT capc.property_contract_id, capc.over_due, capc.contract_id, capc.project_id, capc.product_id, capc.total_principal, capc.total_interest, capc.uncollected_principal, capc.uncollected_interest, capc.document_type, cc.contract_number, cc.contract_name, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE cc.tenant_id = hbm.bp_id ) AS bp_name FROM ct_abs_property_contract capc , con_contract cc where capc.contract_id = cc.contract_id and capc.document_type = 'CON_CONTRACT') t1 1=1
and t1.project_id = #{projectId}
and t1.product_id = #{productId}

SELECT ( CASE document_type WHEN 'CON_CONTRACT' THEN ( SELECT cc.contract_name FROM con_contract cc WHERE cc.contract_id = pc.contract_id ) ELSE ( SELECT fc.contract_name FROM fct_contract fc WHERE fc.contract_id = pc.contract_id ) END ) AS contract_name, ( CASE document_type WHEN 'CON_CONTRACT' THEN ( SELECT cc.contract_number FROM con_contract cc WHERE cc.contract_id = pc.contract_id ) ELSE ( SELECT fc.contract_number FROM fct_contract fc WHERE fc.contract_id = pc.contract_id ) END ) AS contract_number, ( CASE document_type WHEN 'CON_CONTRACT' THEN ( SELECT hbm.bp_name FROM con_contract cc, hls_bp_master hbm WHERE cc.contract_id = pc.contract_id AND cc.tenant_id = hbm.bp_id ) ELSE ( SELECT hbm.bp_name FROM fct_contract fc, hls_bp_master hbm, fct_project_bp fpb WHERE hbm.bp_id = fpb.bp_id AND fpb.project_id = fc.project_id AND fc.contract_id = pc.contract_id AND fpb.credit_grantor_party = 'Y' ) END ) AS bp_name, pc.* FROM ct_abs_property_contract pc pc.product_id is null
and pc.project_id = #{projectId}
and pc.contract_id NOT IN
#{item}

SELECT t1.* FROM ( SELECT cc.contract_id, cc.contract_name, cc.contract_number, cc.company_id, 'CON_CONTRACT' AS document_type, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE cc.tenant_id = hbm.bp_id ) AS bp_name, ( SELECT sum( ccc.principal ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id ) AS total_principal, ( SELECT sum( ccc.interest ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id ) AS total_interest, ( SELECT sum( ccc.principal - ccc.received_principal ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.write_off_flag != 'FULL' AND ccc.due_date > date_add( to_date(#{dateStr},'YYYY-MM-DD'), interval cast(-cc.renting_frequency as unsigned int) month ) ) AS uncollected_principal, ( SELECT sum( ccc.interest - ccc.received_interest ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.write_off_flag != 'FULL' AND ccc.due_date > date_add( to_date(#{dateStr},'YYYY-MM-DD'), interval cast(cc.renting_frequency as unsigned int) month) ) AS uncollected_interest FROM ( SELECT c.contract_id, c.contract_name, c.contract_number, c.company_id, c.data_class, c.contract_status, c.tenant_id, ( CASE c.renting_frequency WHEN 'YEAR' THEN 12 WHEN 'HALF_A_YEAR' THEN 6 WHEN 'QUARTER' THEN 3 ELSE 1 END ) renting_frequency FROM con_contract c ) cc WHERE cc.data_class = 'NORMAL' AND cc.contract_status = 'INCEPT' AND EXISTS ( SELECT 1 FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.write_off_flag != 'FULL' ) UNION SELECT fc.contract_id, fc.contract_name, fc.contract_number, fc.company_id, 'FCT_CONTRACT' AS document_type, ( SELECT hbm.bp_name FROM hls_bp_master hbm, fct_project_bp fpb WHERE hbm.bp_id = fpb.bp_id AND fpb.project_id = fc.project_id AND fpb.credit_grantor_party = 'Y' ) AS bp_name, ( SELECT sum( nvl( fqc.due_amount, 0 ) ) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fc.contract_id AND fqc.cf_item = 54 ) AS total_principal, ( SELECT sum( nvl( fqc.due_amount, 0 ) ) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fc.contract_id AND fqc.cf_item = 55 ) AS total_interest, ( SELECT sum( nvl( fqc.due_amount, 0 ) ) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fc.contract_id AND fqc.write_off_flag != 'FULL' AND fqc.cf_item = 54 AND fqc.due_date > to_date( #{dateStr}, 'YYYY-MM-DD' ) ) AS uncollected_principal, ( SELECT sum( nvl( fqc.due_amount, 0 ) ) FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fc.contract_id AND fqc.write_off_flag != 'FULL' AND fqc.cf_item = 55 AND fqc.due_date > to_date( #{dateStr}, 'YYYY-MM-DD' ) ) AS uncollected_interest FROM fct_contract fc WHERE fc.data_class = 'NORMAL' AND fc.contract_status = 'INCEPT' AND EXISTS ( SELECT 1 FROM fct_quotation_cashflow fqc WHERE fqc.contract_id = fc.contract_id AND fqc.write_off_flag != 'FULL' ) ) t1 1=1
and t1.contract_id = #{contractId}
and t1.document_type = #{documentType}

SELECT ( CASE document_type WHEN 'CON_CONTRACT' THEN ( SELECT cc.contract_name FROM con_contract cc WHERE cc.contract_id = pc.contract_id ) ELSE ( SELECT fc.contract_name FROM fct_contract fc WHERE fc.contract_id = pc.contract_id ) END ) AS contract_name, ( CASE document_type WHEN 'CON_CONTRACT' THEN ( SELECT cc.contract_number FROM con_contract cc WHERE cc.contract_id = pc.contract_id ) ELSE ( SELECT fc.contract_number FROM fct_contract fc WHERE fc.contract_id = pc.contract_id ) END ) AS contract_number, ( CASE document_type WHEN 'CON_CONTRACT' THEN ( SELECT hbm.bp_name FROM con_contract cc, hls_bp_master hbm WHERE cc.contract_id = pc.contract_id AND cc.tenant_id = hbm.bp_id ) ELSE ( SELECT hbm.bp_name FROM fct_contract fc, hls_bp_master hbm, fct_project_bp fpb WHERE hbm.bp_id = fpb.bp_id AND fpb.project_id = fc.project_id AND fc.contract_id = pc.contract_id AND fpb.credit_grantor_party = 'Y' ) END ) AS bp_name, pc.* FROM ct_abs_property_contract pc pc.product_id is null
and pc.project_id = #{projectId}
and pc.property_contract_id NOT IN
#{item}

SELECT ( CASE document_type WHEN 'CON_CONTRACT' THEN ( SELECT cc.contract_name FROM con_contract cc WHERE cc.contract_id = pc.contract_id ) ELSE ( SELECT fc.contract_name FROM fct_contract fc WHERE fc.contract_id = pc.contract_id ) END ) AS contract_name, ( CASE document_type WHEN 'CON_CONTRACT' THEN ( SELECT cc.contract_number FROM con_contract cc WHERE cc.contract_id = pc.contract_id ) ELSE ( SELECT fc.contract_number FROM fct_contract fc WHERE fc.contract_id = pc.contract_id ) END ) AS contract_number, ( CASE document_type WHEN 'CON_CONTRACT' THEN ( SELECT hbm.bp_name FROM con_contract cc, hls_bp_master hbm WHERE cc.contract_id = pc.contract_id AND cc.tenant_id = hbm.bp_id ) ELSE ( SELECT hbm.bp_name FROM fct_contract fc, hls_bp_master hbm, fct_project_bp fpb WHERE hbm.bp_id = fpb.bp_id AND fpb.project_id = fc.project_id AND fc.contract_id = pc.contract_id AND fpb.credit_grantor_party = 'Y' ) END ) AS bp_name, pc.* FROM ct_abs_property_contract pc 1=1
and pc.product_id = #{productId}
and pc.property_contract_id NOT IN
#{item}
